class JuniorResearcher extends Researcher {}

class Team {
  + name : string
}

class Area {
  + name : string
}

class AreaManager {
  + name : string
}

class Project {
  + name : string
}

Area "1" -- "0..*" Team : Groups
Area "1" -- "1" AreaManager : Has
Team "1" -- "1" SeniorResearcher : Led by
Team "1" -- "1..*" JuniorResearcher : Includes
Team "1" -- "0..*" Project : Carries out

@enduml

